import timeimport yamlfrom google import genaifrom google.genai.errors import ServerErrorwith open("my_research_agent/mcp_agent.secrets.yaml") as f:    secrets = yaml.safe_load(f)client = genai.Client(    api_key=secrets["google"]["api_key"])for attempt in range(5):    try:        response = client.models.generate_content(            model="gemini-3.8-flash",            contents="""            You are a business analyst.            What are the three most important factors            a company should consider before entering            a new international market?            """        )        print("\n--- GEMINI RESPONSE ---\n")        print(response.text)        break    except ServerError:        wait = 2 ** attempt        print(f"Gemini busy. Retrying in {wait} seconds...")        time.sleep(wait)else:    print("Gemini is still busy. Try again later.")